import type { MainNavProps } from "./main-nav.types";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants interface (@exp-textura/types)
const componentName = "MainNav";

// Generate child element class names for the component, should match available style slots
export const MainNavClasses = {
  root: "exp-textura_main-nav",
  brand: "exp-textura_main-nav_brand",
  header: "exp-textura_main-nav_header",
  content: "exp-textura_main-nav_content",
  footer: "exp-textura_main-nav_footer",
  divider: "exp-textura_main-nav_divider",
  collapseTrigger: "exp-textura_main-nav_collapse_trigger",
  item: "exp-textura_main-nav_item",
  itemInlineBadge: "exp-textura_main-nav_item_inline_badge",
  indicator: "exp-textura_main-nav_indicator",
  user: "exp-textura_main-nav_user",
  iconSwap: "exp-textura_main-nav_icon_swap",
  iconSwapDefault: "exp-textura_main-nav_icon_swap_default",
  iconSwapHover: "exp-textura_main-nav_icon_swap_hover",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: MainNavProps) => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<MainNavProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    flexDirection: "column",
    height: "100vh",
    overflow: "hidden",
    zIndex: theme.zIndex.dynamic,
    backgroundColor: theme.mainNav.backgroundColor,
    color: theme.mainNav.color,
    fontFamily: theme.typography.fontFamily.plusJakartaSans,
    fontWeight: theme.typography.fontWeight[400],
    fontSize: theme.typography.fontSize[14],
    letterSpacing: theme.typography.letterSpacing[0],
    lineHeight: theme.typography.lineHeight[20],
    transitionDuration: theme.mainNav.transitionDuration,
    transition: `width ${theme.mainNav.transitionDuration} ease`,

    "&& *:focus-visible": {
      ...theme.focusRingInverse,
    },

    '&[data-main-nav-state="expanded"]': {
      width: theme.toRem(216),
      ...styleSlots?.expanded,
    },

    '&[data-main-nav-state="collapsed"]': {
      width: theme.toRem(48),
      ...styleSlots?.collapsed,
    },

    [`.${MainNavClasses.header}`]: {
      position: "relative",
      padding: `0 ${theme.toRem(12)}`,
      transition: `padding ${theme.mainNav.transitionDuration} ease`,
      "&[data-main-nav-state='collapsed']": {
        padding: `0 ${theme.toRem(8)}`,
      },
      [`> .${MainNavClasses.divider}`]: {
        marginTop: theme.toRem(12),
        marginBottom: 0,
      },
      ...styleSlots?.header,
    },

    [`.${MainNavClasses.content}`]: {
      display: "flex",
      flex: 1,
      flexDirection: "column",
      gap: theme.toRem(4),
      padding: `${theme.toRem(12)} ${theme.toRem(12)} ${theme.toRem(8)} ${theme.toRem(12)}`,
      overflow: "auto",
      transition: `padding ${theme.mainNav.transitionDuration} ease`,
      "&[data-main-nav-state='collapsed']": {
        padding: `${theme.toRem(12)} ${theme.toRem(8)} ${theme.toRem(8)} ${theme.toRem(8)}`,
      },
      "::-webkit-scrollbar": {
        display: "none",
      },
      MsOverflowStyle: "none" /* IE and Edge */,
      scrollbarWidth: "none" /* Firefox */,
      ...styleSlots?.content,
    },

    [`.${MainNavClasses.footer}`]: {
      display: "flex",
      marginTop: "auto",
      flexDirection: "column",
      justifyContent: "center",
      gap: theme.toRem(4),
      padding: `${theme.toRem(8)} ${theme.toRem(12)} ${theme.toRem(16)} ${theme.toRem(12)}`,
      transition: `padding ${theme.mainNav.transitionDuration} ease`,
      "&[data-main-nav-state='collapsed']": {
        padding: `${theme.toRem(8)} ${theme.toRem(8)} ${theme.toRem(16)} ${theme.toRem(8)}`,
      },
      ...styleSlots?.footer,
    },

    [`.${MainNavClasses.brand}`]: {
      backgroundColor: "transparent",
      display: "flex",
      alignItems: "center",
      width: theme.toRem(28),
      height: theme.toRem(28),
      maxHeight: theme.toRem(28),
      cursor: "pointer",
      marginTop: theme.toRem(13),
      marginBottom: theme.toRem(12),
      marginInlineStart: theme.toRem(2),
      "&:focus-visible": {
        ...styleSlots?.brandFocus,
      },
      "&:hover": {
        ...styleSlots?.brandHover,
      },
      [`&[data-main-nav-state="expanded"]`]: {
        width: theme.toRem(80),
        marginInlineStart: theme.toRem(8),
        "> :first-of-type": {
          maxHeight: theme.toRem(20),
        },
      },
      "> :first-of-type": {
        all: "unset",
        height: theme.toRem(28),
        maxHeight: theme.toRem(28),
      },
      ...styleSlots?.brand,
    },

    [`.${MainNavClasses.collapseTrigger}`]: {
      position: "absolute",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      height: theme.toRem(32),
      width: theme.toRem(32),
      top: theme.toRem(12),
      backgroundColor: "transparent",
      border: "none",
      color: theme.color.content.inverse,
      borderRadius: theme.toRem(theme.border.radius.sm),
      cursor: "pointer",
      "&:focus-visible": {
        ...styleSlots?.collapseTriggerFocus,
      },
      "&:hover:enabled": {
        backgroundColor: theme.mainNav.selectTriggerHover,
        color: theme.color.content.inverse,
        ...styleSlots?.collapseTriggerHover,
      },
      svg: {
        fontSize: theme.toRem(16),
        minWidth: theme.toRem(16),
      },
      [`&[data-main-nav-state="expanded"]`]: {
        insetInlineEnd: theme.toRem(12),
      },
      [`&[data-main-nav-state="collapsed"]`]: {
        color: "transparent",
      },
      ...styleSlots?.collapseTrigger,
    },

    [`.${MainNavClasses.item}`]: {
      all: "unset",
      minHeight: theme.toRem(20),
      backgroundColor: "transparent",
      display: "flex",
      alignItems: "center",
      border: "none",
      justifyContent: "flex-start",
      color: theme.color.brand.primary.ivory,
      padding: `${theme.toRem(6)} ${theme.toRem(8)}`,
      overflow: "hidden",
      borderRadius: theme.toRem(theme.border.radius.sm),
      gap: theme.toRem(8),
      ...theme.typography.label.md,
      lineHeight: theme.typography.lineHeight[20],
      cursor: "pointer",
      textDecoration: "none",
      width: "fill-available",
      whiteSpace: "nowrap",
      "&:focus-visible": {
        ...styleSlots?.itemFocus,
      },
      "&:hover:not([data-main-nav-item-current]), &[data-state=open]:not([data-main-nav-item-current])":
        {
          backgroundColor: theme.mainNav.backgroundColorExpanded,
          color: theme.mainNav.color,
          [`.${MainNavClasses.iconSwap} .${MainNavClasses.iconSwapHover}`]: {
            display: "inline-flex",
          },
          [`.${MainNavClasses.iconSwap} .${MainNavClasses.iconSwapDefault}`]: {
            display: "none",
          },
          ...styleSlots?.itemHover,
        },
      "&:disabled, &:disabled:hover": {
        cursor: "not-allowed",
        backgroundColor: "transparent",
        color: theme.color.content.actionInverseDisabled,
        opacity: 0.5,
        ...styleSlots?.itemDisabled,
      },
      svg: {
        fontSize: theme.toRem(16),
        minWidth: theme.toRem(16),
      },
      [`.${MainNavClasses.iconSwap}`]: {
        position: "relative",
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        [`.${MainNavClasses.iconSwapHover}`]: {
          display: "none",
          ...styleSlots?.iconSwapHover,
        },
        [`.${MainNavClasses.iconSwapDefault}`]: {
          display: "inline-flex",
          ...styleSlots?.iconSwapDefault,
        },
        ...styleSlots?.iconSwap,
      },
      "&[data-main-nav-item-current]": {
        backgroundColor: theme.mainNav.backgroundColorSelected,
        color: theme.mainNav.backgroundColor,
        cursor: "default",
        ...styleSlots?.itemCurrent,
      },
      ...styleSlots?.item,
    },

    [`.${MainNavClasses.itemInlineBadge}`]: {
      marginInlineStart: "auto",
      ...styleSlots?.itemInlineBadge,
    },

    [`.${MainNavClasses.indicator}`]: {
      flex: 1,
      display: "flex",
      justifyContent: "flex-end",
      ":dir(rtl)": {
        transform: "scaleX(-1)",
        justifyContent: "flex-start",
      },
      ...styleSlots?.indicator,
    },

    [`.${MainNavClasses.user}`]: {
      paddingTop: theme.toRem(4),
      paddingBottom: theme.toRem(4),
      paddingInlineStart: theme.toRem(8),
      paddingInlineEnd: theme.toRem(8),
      fontSize: theme.typography.fontSize[12],
      wordSpacing: 9999,
      whiteSpace: "normal",
      textAlign: "start",
      gap: theme.toRem(12),
      transition: `all ${theme.mainNav.transitionDuration} ease`,
      minHeight: theme.toRem(36),
      lineHeight: theme.typography.lineHeight[16],
      "&[data-main-nav-state='collapsed']": {
        paddingInlineStart: theme.toRem(4),
        paddingInlineEnd: theme.toRem(4),
        "&:hover": {
          backgroundColor: "transparent !important",
        },
      },
      "&:focus-visible": {
        ...styleSlots?.userFocus,
      },
      "&:hover": {
        ...styleSlots?.userHover,
      },
      ...styleSlots?.user,
    },

    [`.${MainNavClasses.divider}`]: {
      ...styleSlots?.divider,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledMainNav = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<MainNavProps>((props) => generateStyles(props));
